func swapTwo<T>(_ a: inout T, _ b: inout T) {
    let t = a; a = b; b = t
}
var x = "a", y = "b"
swapTwo(&x, &y)
print(x, y) // b a

func largest<T: Comparable>(_ a: [T]) -> T? {
    guard var m = a.first else { return nil }
    for v in a where v > m { m = v }
    return m
}
print(largest([3, 9, 2]) ?? 0, largest(["b", "z"]) ?? "")

struct Stack<Element> {
    private var items: [Element] = []
    mutating func push(_ e: Element) { items.append(e) }
    mutating func pop() -> Element? { items.popLast() }
}
var s = Stack<Int>()
s.push(1); s.push(2)
print(s.pop() ?? 0) // 2

